import"./firebase-DHk78Ngz.js";window.submitBarberForm=async e=>{e.preventDefault();let t=e.target.querySelector(`.form-submit`);t.textContent=`Submitting...`,t.disabled=!0;let n=e.target,r=n.querySelectorAll(`input, select, textarea`);try{let e=window.TRIMZY_CONFIG?.API_URL||`https://trimzy-backend.onrender.com/api`,t={name:r[0].value.trim(),phone:r[1].value.trim(),email:r[2].value.trim(),area:r[3].value.trim(),shopName:r[0].value.trim()+`'s Shop`},i=await fetch(`${e}/admin/applications`,{method:`POST`,headers:{"Content-Type":`application/json`},body:JSON.stringify(t)});if(!i.ok){let e=await i.json();throw Error(e.error||`Failed to submit application`)}document.getElementById(`success-overlay`).classList.add(`show`),n.reset()}catch(e){alert(e.message||`Something went wrong. Please check your connection and try again.`),console.error(e)}finally{t.textContent=`Submit Application →`,t.disabled=!1}};